def get_pings(self) -> list[ServicePing]:
    """
    Return all services that have defined a *ping* and bind them to this
    container.

    Returns:
        A list of services that have registered a ping callable.
    """
    pings: dict[type, ServicePing] = {}

    # First, gather pings from the registry.
    for rs in self.registry._services.values():
        if rs.ping is not None:
            pings[rs.svc_type] = ServicePing(
                rs.name,
                iscoroutinefunction(rs.ping),
                rs.svc_type,
                rs.ping,
                self,
            )

    # Then, overwrite or add pings from local registrations.
    if self._lazy_local_registry is not None:
        for rs in self._lazy_local_registry._services.values():
            if rs.ping is not None:
                pings[rs.svc_type] = ServicePing(
                    rs.name,
                    iscoroutinefunction(rs.ping),
                    rs.svc_type,
                    rs.ping,
                    self,
                )
            elif rs.svc_type in pings:
                # Local registration exists for this type but has no ping,
                # so it shadows the registry's ping.
                del pings[rs.svc_type]

    return list(pings.values())

